import{_ as i,l as r,o as e,c as p,v as t,p as s,x as o,d as E,i as n,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"光瞳图优化","description":"","frontmatter":{"title":"光瞳图优化","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/pupil-source-map.md","filePath":"litho/pupil-source-map.md","lastUpdated":1789023840000}'),d={name:"litho/pupil-source-map.md"};function c(A,a,u,m,B,_){const l=r("Mermaid");return e(),p("div",null,[a[1]||(a[1]=t('<h1 id="光瞳图优化" tabindex="-1">光瞳图优化 <a class="header-anchor" href="#光瞳图优化" aria-label="Permalink to &quot;光瞳图优化&quot;">​</a></h1><div class="epigraph"><p>自由光源不是把瞳面调亮，而是把能量像素化地分配到能形成干涉的那些点上；花瓣图若不能被扫描仪实现，只是计算域里的最优。</p><footer>—— 对照 ASML 对 SMO 与自由成形照明的公开论述</footer></div><p><a href="/litho/smo">上一课</a>已经把 SMO 收成光源与掩模的联合逆问题：光瞳改 TCC，掩模在既定通带里修边。缺口是光源那一侧的表示。传统 RET 只在常规、环形、偶极、四极里选；自由光瞳把瞳面切成像素（或极坐标基），每个像素的强度成为优化变量。本课钉光瞳图。像差与波前如何再进协同，留给<a href="/litho/smo-plus-wavefront">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>部分相干成像里，光源上每一点对应一组倾斜照明。像素化之后，变量数从「几个 σ 和叶片角」变成几百到上千个瞳面自由度。可行集变大，二维逻辑与 SRAM 的窗口交才有机会同时活；可行集也变脏：扫描仪的柔性照明器有最小特征、能量效率、热负载和衍射光学元件的可制造性。优化若不管这些，会输出一张漂亮但照不出来的灰度图。</p><p>目标函数必须是一批关键 clips 的窗口交，而不是单条密线的对比冠军。某一像素变亮，可能抬高某一取向的 NILS，同时让正交取向的焦深崩溃。缺口因此是：在可实现光瞳上搜，而不是在任意 \\(L^2\\) 函数上搜。</p><h3 id="像素不是独立旋钮" tabindex="-1">像素不是独立旋钮 <a class="header-anchor" href="#像素不是独立旋钮" aria-label="Permalink to &quot;像素不是独立旋钮&quot;">​</a></h3><p>相邻像素通过光学传递和照明器约束耦合。把 SMO 理解成「每个像素调一个百分比」会得到高频噪声光瞳，成形效率差、对对准误差敏感。工程上要平滑、对称（或按 EUV 阴影故意不对称）、以及最小孤岛尺寸。ASML 公开的自由光源能力，指的是照明器能逼近的那类图，不是任意位图。</p><p><span class="marginnote">光瞳图的坐标是照明瞳，不是投影物镜的成像瞳。两者相关但不是同一张图。把 SMO 输出直接当成波前校正图，会把下一课的自由度提前用错。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>典型参数化：笛卡尔像素、扇区、或 Zernike/极坐标基。优化在代表性单元、SRAM、孔与切层 clips 上跑，掩模用边碎片或粗像素，成本含 PV-band、MEEF、ILS，外加光源传输惩罚。收敛后把连续图投影到照明器可实现集合（叶片、DOE、FlexRay 一类柔性照明的公开能力），再冻结，全芯片 <a href="/litho/opc">OPC</a> 或 ILT。</p><p>EUV 上 6° 主光线让水平/垂直不对称，光瞳图常常是取向相关的自由形状，再由设计规则限制允许节距。DUV 浸没已经证明自由光源能在不改 NA 时再挖一截 \\(k_1\\)；EUV 上这一截用来换更少双重，或给随机预算留对比余量。</p><h3 id="从种子到可实现投影" tabindex="-1">从种子到可实现投影 <a class="header-anchor" href="#从种子到可实现投影" aria-label="Permalink to &quot;从种子到可实现投影&quot;">​</a></h3><p>从环形或偶极种子出发，比从白噪声瞳开始更稳，因为目标非凸。投影步骤不可省：计算最优与机台最优之间的差，要在硅上验证，不能只报优化器 loss。传输过低的光瞳会拉长扫描时间，把<a href="/litho/photon-shot-budget">光子预算</a>的剂量上限往下拉——光瞳图因此也是产能图。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Hopkins 的 TCC 由光源与瞳函数决定。改像素即改 TCC 的谱结构，空中像算子的本征方向跟着转。掩模变量通过这个算子映射到轮廓。联合优化在「光源可行集 × 掩模可行集」上走；光源是场级全局变量，所以只能在抽样 clips 上动光瞳，不能让每一标准单元拥有自己的光瞳。</p><p>MEEF 把掩模误差放大。某些高对比光瞳把 MEEF 抬到掩模厂接不住。光瞳图优化必须把 MEEF 与 MRC 放进成本，否则窗口数字好看，版写不出来。</p><p><span class="marginnote">宣传材料里的花瓣光瞳若没有对应的掩模协同和全芯片 OPC，只是照明器能力演示。评价要看冻结该光瞳之后全芯片的 PV-band，而不是 clips 上的对比度冠军。</span></p>',18)),(e(),s(h,null,{default:o(()=>[n(l,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20PIX%5B%22%E5%85%89%E7%9E%B3%E5%83%8F%E7%B4%A0%22%5D%20--%3E%20TCC%5B%22TCC%20%2F%20%E5%B9%B2%E6%B6%89%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20MSK%5B%22%E6%8E%A9%E6%A8%A1%E5%8F%98%E9%87%8F%22%5D%20--%3E%20IMG%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%22%5D%0A%20%20TCC%20--%3E%20IMG%0A%20%20IMG%20--%3E%20COST%5B%22%E7%AA%97%E5%8F%A3%E4%BA%A4%20%2B%20MEEF%20%2B%20%E4%BC%A0%E8%BE%93%22%5D%0A%20%20COST%20--%3E%20PROJ%5B%22%E6%8A%95%E5%BD%B1%E5%88%B0%E5%8F%AF%E5%AE%9E%E7%8E%B0%E7%85%A7%E6%98%8E%22%5D%0A%20%20PROJ%20--%3E%20OPC%5B%22%E5%86%BB%E7%BB%93%E5%90%8E%E5%85%A8%E8%8A%AF%E7%89%87%20OPC%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>光瞳图优化不增加 NA，不缩短波长。它只在现有透镜通带里重新分配能量。未抽到的热区会在量产中冒出来，通常用 OPC 补丁，而不是每周改光瞳——光源一改，所有层 OPC 重放。计算量在定规则阶段，真正的 CPU/GPU 墙仍在全芯片修正。</p><p>后课默认：自由光瞳是像素化并可投影到照明器的那张图；下一课再把投影光学的波前自由度加进去。</p><p><span class="marginnote">比较两张光瞳要同时报：关键图形窗口交、MEEF、照明效率、以及换成该光源后 OPC 的掩模复杂度。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>光瞳图优化把照明能量像素化，改的是干涉条件，不是总亮度。</li><li>必须投影到扫描仪可实现集合，否则最优不可照明。</li><li>光源是场级变量，只在代表性 clips 上优化再冻结。</li><li>EUV 阴影让自由光瞳取向相关；MEEF 与产率必须进成本。</li><li>出处：ASML 关于 SMO 与自由成形光源的公开方法。</li></ul>',6))])}const f=i(d,[["render",c]]);export{P as __pageData,f as default};
